import importlib, os

class PluginBase:
    def execute(self): raise NotImplementedError

def load_plugins(plugin_dir='plugins'):
    loaded = []
    for fname in os.listdir(plugin_dir):
        if fname.endswith('.py') and not fname.startswith('__'):
            mod_name = f'{plugin_dir}.{fname[:-3]}'
            mod = importlib.import_module(mod_name)
            for attr in dir(mod):
                obj = getattr(mod, attr)
                if isinstance(obj, type) and issubclass(obj, PluginBase) and obj is not PluginBase:
                    loaded.append(obj())
    return loaded

def migrate_v1_to_v2(data):
    data['timeout'] = data.pop('time_limit', 30)
    data['version'] = 2
    return data

def migrate_v2_to_v3(data):
    data['retries'] = 3
    data['version'] = 3
    return data

MIGRATIONS = {1: migrate_v1_to_v2, 2: migrate_v2_to_v3}

def load_and_migrate(raw_json):
    current_version = raw_json.get('version', 1)
    while current_version in MIGRATIONS:
        raw_json = MIGRATIONS[current_version](raw_json)
        current_version = raw_json['version']
    return raw_json
